#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const int n = static_cast<int>(x.size());
    output.assign(n, 0);
    if (n == 0) return;

    int P = omp_get_max_threads();
    if (P > n) P = n;
    if (P <= 1) {
        int run = 0;
        for (int i = n - 1; i >= 0; --i) {
            run += x[i];
            output[i] = run;
        }
        return;
    }

    std::vector<int> blockSum(P, 0);
    std::vector<int> blockOffset(P, 0);

    const int base = n / P;
    const int rem  = n % P;

    auto start_of = [&](int t) -> int {
        // contiguous blocks: first 'rem' blocks have size base+1
        return t * base + (t < rem ? t : rem);
    };
    auto size_of = [&](int t) -> int { return base + (t < rem ? 1 : 0); };
    auto end_of  = [&](int t) -> int { return start_of(t) + size_of(t); }; // exclusive

#pragma omp parallel num_threads(P)
    {
        const int tid = omp_get_thread_num();
        const int s = start_of(tid);
        const int e = end_of(tid);

        // Local reverse prefix sum within block (store temporary results as if offset were 0)
        int run = 0;
        for (int i = e - 1; i >= s; --i) {
            run += x[i];
            output[i] = run;
        }
        blockSum[tid] = run;

#pragma omp barrier

#pragma omp single
        {
            // Compute offsets: sum of all blocks to the right
            int acc = 0;
            for (int t = P - 1; t >= 0; --t) {
                blockOffset[t] = acc;
                acc += blockSum[t];
            }
        }

#pragma omp barrier

        // Add the block offset to each element in this block
        const int off = blockOffset[tid];
        for (int i = s; i < e; ++i) {
            output[i] += off;
        }
    }
}
